draw:
var kp = p.k1 + p.k2;
var ks = (p.k1 * p.k2) / (p.k1 + p.k2);
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;

function coilH(x0, x1, y, turns) {
  ctx.strokeStyle = C.accent;
  ctx.beginPath();
  ctx.moveTo(x0, y);
  var i;
  for (i = 1; i <= turns; i++) {
    var xx = x0 + (x1 - x0) * i / turns;
    var yy = y + (i % 2 === 0 ? -8 : 8) * (i === turns ? 0 : 1);
    ctx.lineTo(xx, yy);
  }
  ctx.lineTo(x1, y);
  ctx.stroke();
}

var leftW = W * 0.46;
var wallA = W * 0.05, massA = W * 0.36;
var yA1 = H * 0.22, yA2 = H * 0.40;
ctx.fillStyle = C.faint;
ctx.fillRect(wallA - 8, yA1 - 26, 8, (yA2 - yA1) + 52);
coilH(wallA, massA, yA1, 10);
coilH(wallA, massA, yA2, 10);
ctx.fillStyle = C.figure;
ctx.fillRect(massA, yA1 - 14, 26, (yA2 - yA1) + 28);
ctx.fillStyle = C.ink;
ctx.fillText("k1", (wallA + massA) / 2 - 6, yA1 - 16);
ctx.fillText("k2", (wallA + massA) / 2 - 6, yA2 + 26);
ctx.fillStyle = C.faint;
ctx.fillText("parallel: same stretch, forces add", wallA, H * 0.60);
ctx.fillStyle = C.accent;
ctx.fillText("k = k1 + k2 = " + kp.toFixed(0) + " N/m", wallA, H * 0.72);

var wallB = W * 0.56, midB = W * 0.74, massB = W * 0.90;
var yB = H * 0.30;
ctx.fillStyle = C.faint;
ctx.fillRect(wallB - 8, yB - 26, 8, 52);
coilH(wallB, midB, yB, 8);
coilH(midB, massB - 4, yB, 8);
ctx.fillStyle = C.rule;
ctx.beginPath(); ctx.arc(midB, yB, 4, 0, 6.2832); ctx.fill();
ctx.fillStyle = C.figure;
ctx.fillRect(massB - 4, yB - 16, 24, 32);
ctx.fillStyle = C.ink;
ctx.fillText("k1", (wallB + midB) / 2 - 6, yB - 18);
ctx.fillText("k2", (midB + massB) / 2 - 6, yB - 18);
ctx.fillStyle = C.faint;
ctx.fillText("series: same force, stretches add", wallB, H * 0.60);
ctx.fillStyle = C.accent;
ctx.fillText("1/k = 1/k1 + 1/k2 -> " + ks.toFixed(1) + " N/m", wallB, H * 0.72);

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(W * 0.51, H * 0.10); ctx.lineTo(W * 0.51, H * 0.80); ctx.stroke();

out.note = "parallel k = " + kp.toFixed(0) + " N/m, series k = " + ks.toFixed(1) + " N/m (series is softer than either spring)";
